candidates.raw:
double n;
double d;
adcs_vec3_t diff;
unint32 i;
int valid = 1;

/* 1) validate inputs/config */
if (gb_input.rate_rad_s == NULL) valid = 0;
if (!isfinite(gb_config.stationary_limit_rad_s) || gb_config.stationary_limit_rad_s < 0.0) valid = 0;
if (!isfinite(gb_config.max_sample_delta_rad_s) || gb_config.max_sample_delta_rad_s < 0.0) valid = 0;
if (!isfinite(gb_config.max_stddev_rad_s) || gb_config.max_stddev_rad_s < 0.0) valid = 0;
if (gb_config.required_samples < 3U || gb_config.required_samples > 100U) valid = 0;
if (gb_config.max_rejected_windows < 1U || gb_config.max_rejected_windows > 20U) valid = 0;
if (!isfinite(gb_config.drift_limit_rad_s) || gb_config.drift_limit_rad_s < 0.0) valid = 0;
if (gb_config.drift_confirm_samples < 1U || gb_config.drift_confirm_samples > 20U) valid = 0;
if (gb_input.enable != 0 && gb_input.enable != 1) valid = 0;

if (!valid) {
    gb_state.mode = GB_FAULT;
    gb_output.mode = GB_FAULT;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_output.variance_rad_s2 = (adcs_vec3_t){0, 0, 0};
    gb_output.count = gb_state.count;
    gb_output.rejected_windows = gb_state.rejected_windows;
    return;
}

/* 2) disable clears all state */
if (gb_input.enable == 0) {
    gb_state.mode = GB_OFF;
    gb_state.count = 0U;
    gb_state.rejected_windows = 0U;
    gb_state.has_previous = 0;
    gb_state.mean_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.m2_rad_s2 = (adcs_vec3_t){0, 0, 0};
    gb_state.previous_rate_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.bias_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.variance_rad_s2 = (adcs_vec3_t){0, 0, 0};
    gb_state.drift_count = 0U;
    gb_output.mode = GB_OFF;
    gb_output.count = 0U;
    gb_output.rejected_windows = 0U;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_output.variance_rad_s2 = (adcs_vec3_t){0, 0, 0};
    return;
}

/* 3) invalid rate input faults even while READY */
if (!adcs_is_finite_vec3(gb_input.rate_rad_s)) {
    gb_state.mode = GB_FAULT;
    gb_output.mode = GB_FAULT;
    gb_output.count = gb_state.count;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_output.variance_rad_s2 = (adcs_vec3_t){0, 0, 0};
    return;
}

/* 4) FAULT: just publish */
if (gb_state.mode == GB_FAULT) {
    gb_output.mode = GB_FAULT;
    gb_output.count = gb_state.count;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_output.variance_rad_s2 = (adcs_vec3_t){0, 0, 0};
    return;
}

/* 5) READY: drift monitoring */
if (gb_state.mode == GB_READY) {
    diff = adcs_vec3_sub(gb_input.rate_rad_s, &gb_state.bias_rad_s);
    n = adcs_vec3_norm(&diff);
    if (n <= gb_config.drift_limit_rad_s) {
        gb_state.drift_count = 0U;
    } else {
        gb_state.drift_count++;
        if (gb_state.drift_count >= gb_config.drift_confirm_samples) {
            gb_state.mode = GB_COLLECT;
            gb_state.count = 0U;
            gb_state.has_previous = 0;
            gb_state.mean_rad_s = (adcs_vec3_t){0, 0, 0};
            gb_state.m2_rad_s2 = (adcs_vec3_t){0, 0, 0};
            gb_state.previous_rate_rad_s = (adcs_vec3_t){0, 0, 0};
            gb_state.bias_rad_s = (adcs_vec3_t){0, 0, 0};
            gb_state.variance_rad_s2 = (adcs_vec3_t){0, 0, 0};
            gb_state.drift_count = 0U;
        }
    }
    if (gb_state.mode == GB_READY) {
        gb_output.mode = GB_READY;
        gb_output.count = gb_state.count;
        gb_output.rejected_windows = gb_state.rejected_windows;
        gb_output.rejection = GB_REJECT_NONE;
        gb_output.bias_rad_s = gb_state.bias_rad_s;
        gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
        return;
    }
}

/* 6) COLLECT */
gb_state.mode = GB_COLLECT;

n = adcs_vec3_norm(gb_input.rate_rad_s);
if (n > gb_config.stationary_limit_rad_s) {
    gb_state.rejected_windows++;
    gb_state.count = 0U;
    gb_state.has_previous = 0;
    gb_state.mean_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.m2_rad_s2 = (adcs_vec3_t){0, 0, 0};
    gb_state.previous_rate_rad_s = (adcs_vec3_t){0, 0, 0};
    if (gb_state.rejected_windows >= gb_config.max_rejected_windows) {
        gb_state.mode = GB_FAULT;
        gb_output.mode = GB_FAULT;
    } else {
        gb_output.mode = GB_COLLECT;
    }
    gb_output.count = gb_state.count;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = GB_REJECT_RATE;
    gb_output.bias_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_output.variance_rad_s2 = (adcs_vec3_t){0, 0, 0};
    return;
}

if (gb_state.has_previous) {
    diff = adcs_vec3_sub(gb_input.rate_rad_s, &gb_state.previous_rate_rad_s);
    n = adcs_vec3_norm(&diff);
    if (n > gb_config.max_sample_delta_rad_s) {
        gb_state.rejected_windows++;
        gb_state.count = 0U;
        gb_state.has_previous = 0;
        gb_state.mean_rad_s = (adcs_vec3_t){0, 0, 0};
        gb_state.m2_rad_s2 = (adcs_vec3_t){0, 0, 0};
        gb_state.previous_rate_rad_s = (adcs_vec3_t){0, 0, 0};
        if (gb_state.rejected_windows >= gb_config.max_rejected_windows) {
            gb_state.mode = GB_FAULT;
            gb_output.mode = GB_FAULT;
        } else {
            gb_output.mode = GB_COLLECT;
        }
        gb_output.count = gb_state.count;
        gb_output.rejected_windows = gb_state.rejected_windows;
        gb_output.rejection = GB_REJECT_STEP;
        gb_output.bias_rad_s = (adcs_vec3_t){0, 0, 0};
        gb_output.variance_rad_s2 = (adcs_vec3_t){0, 0, 0};
        return;
    }
}

/* accept sample: Welford update */
{
    adcs_vec3_t x = *gb_input.rate_rad_s;
    double cnt;
    adcs_vec3_t delta, delta2;
    gb_state.count++;
    cnt = (double)gb_state.count;
    delta = adcs_vec3_sub(&x, &gb_state.mean_rad_s);
    gb_state.mean_rad_s.x += delta.x / cnt;
    gb_state.mean_rad_s.y += delta.y / cnt;
    gb_state.mean_rad_s.z += delta.z / cnt;
    delta2 = adcs_vec3_sub(&x, &gb_state.mean_rad_s);
    gb_state.m2_rad_s2.x += delta.x * delta2.x;
    gb_state.m2_rad_s2.y += delta.y * delta2.y;
    gb_state.m2_rad_s2.z += delta.z * delta2.z;
    gb_state.previous_rate_rad_s = x;
    gb_state.has_previous = 1;
}

/* at required_samples: check variance */
if (gb_state.count >= gb_config.required_samples) {
    double max_var = gb_config.max_stddev_rad_s * gb_config.max_stddev_rad_s;
    double cnt = (double)gb_state.count;
    double vx = gb_state.m2_rad_s2.x / cnt;
    double vy = gb_state.m2_rad_s2.y / cnt;
    double vz = gb_state.m2_rad_s2.z / cnt;
    int ok = 1;
    if (vx > max_var) ok = 0;
    if (vy > max_var) ok = 0;
    if (vz > max_var) ok = 0;
    if (ok) {
        gb_state.mode = GB_READY;
        gb_state.bias_rad_s = gb_state.mean_rad_s;
        gb_state.variance_rad_s2 = (adcs_vec3_t){vx, vy, vz};
        gb_state.drift_count = 0U;
        gb_output.mode = GB_READY;
        gb_output.count = gb_state.count;
        gb_output.rejected_windows = gb_state.rejected_windows;
        gb_output.rejection = GB_REJECT_NONE;
        gb_output.bias_rad_s = gb_state.bias_rad_s;
        gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
        return;
    }
    gb_state.rejected_windows++;
    gb_state.count = 0U;
    gb_state.has_previous = 0;
    gb_state.mean_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.m2_rad_s2 = (adcs_vec3_t){0, 0, 0};
    gb_state.previous_rate_rad_s = (adcs_vec3_t){0, 0, 0};
    if (gb_state.rejected_windows >= gb_config.max_rejected_windows) {
        gb_state.mode = GB_FAULT;
        gb_output.mode = GB_FAULT;
    } else {
        gb_output.mode = GB_COLLECT;
    }
    gb_output.count = gb_state.count;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = GB_REJECT_VARIANCE;
    gb_output.bias_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_output.variance_rad_s2 = (adcs_vec3_t){0, 0, 0};
    return;
}

/* ordinary collection publish: current population variance */
{
    double cnt = (double)gb_state.count;
    gb_output.mode = GB_COLLECT;
    gb_output.count = gb_state.count;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_output.variance_rad_s2 = (adcs_vec3_t){
        (cnt > 0.0) ? gb_state.m2_rad_s2.x / cnt : 0.0,
        (cnt > 0.0) ? gb_state.m2_rad_s2.y / cnt : 0.0,
        (cnt > 0.0) ? gb_state.m2_rad_s2.z / cnt : 0.0};
}

