            n = (double)gb_state.count;
            delta = adcs_vec3_sub(&rate, &gb_state.mean_rad_s);
            new_mean.x = gb_state.mean_rad_s.x + delta.x / n;
            new_mean.y = gb_state.mean_rad_s.y + delta.y / n;
            new_mean.z = gb_state.mean_rad_s.z + delta.z / n;
            delta2 = adcs_vec3_sub(&rate, &new_mean);
            gb_state.m2_rad_s2.x += delta.x * delta2.x;
            gb_state.m2_rad_s2.y += delta.y * delta2.y;
            gb_state.m2_rad_s2.z += delta.z * delta2.z;
            gb_state.mean_rad_s = new_mean;
            gb_state.previous_rate_rad_s = rate;
        }
    } else {
        double n;
        adcs_vec3_t delta, delta2, new_mean;
        gb_state.count++;
        n = (double)gb_state.count;
        delta = adcs_vec3_sub(&rate, &gb_state.mean_rad_s);
        new_mean.x = gb_state.mean_rad_s.x + delta.x / n;
