            if (ok) {
                gb_state.bias_rad_s = gb_state.mean_rad_s;
                gb_state.variance_rad_s2.x = var[0];
                gb_state.variance_rad_s2.y = var[1];
                gb_state.variance_rad_s2.z = var[2];
                gb_state.drift_count = 0U;
                gb_state.mode = GB_READY;
