    gb_state.mean_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.m2_rad_s2 = (adcs_vec3_t){0, 0, 0};
    gb_state.previous_rate_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.bias_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.variance_rad_s2 = (adcs_vec3_t){0, 0, 0};
    gb_output.mode = GB_FAULT;
    gb_output.count = 0U;
    gb_output.rejected_windows = 0U;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s.x = 0.0;
    gb_output.bias_rad_s.y = 0.0;
    gb_output.bias_rad_s.z = 0.0;
    gb_output.variance_rad_s2.x = 0.0;
    gb_output.variance_rad_s2.y = 0.0;
    gb_output.variance_rad_s2.z = 0.0;
    return;
}

/* input validity */
if ((gb_input.enable != 0 && gb_input.enable != 1) ||
    (gb_input.rate_rad_s == NULL) ||
    (!adcs_is_finite_vec3(gb_input.rate_rad_s))) {
    gb_state.mode = GB_FAULT;
    gb_state.count = 0U;
    gb_state.rejected_windows = 0U;
    gb_state.has_previous = 0;
    gb_state.drift_count = 0U;
    gb_state.mean_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.m2_rad_s2 = (adcs_vec3_t){0, 0, 0};
    gb_state.previous_rate_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.bias_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.variance_rad_s2 = (adcs_vec3_t){0, 0, 0};
    gb_output.mode = GB_FAULT;
    gb_output.count = 0U;
    gb_output.rejected_windows = 0U;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s.x = 0.0;
    gb_output.bias_rad_s.y = 0.0;
    gb_output.bias_rad_s.z = 0.0;
    gb_output.variance_rad_s2.x = 0.0;
    gb_output.variance_rad_s2.y = 0.0;
    gb_output.variance_rad_s2.z = 0.0;
    return;
}

/* disable clears all state */
if (gb_input.enable == 0) {
    gb_state.mode = GB_OFF;
    gb_state.count = 0U;
    gb_state.rejected_windows = 0U;
    gb_state.has_previous = 0;
    gb_state.drift_count = 0U;
    gb_state.mean_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.m2_rad_s2 = (adcs_vec3_t){0, 0, 0};
    gb_state.previous_rate_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.bias_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.variance_rad_s2 = (adcs_vec3_t){0, 0, 0};
    gb_output.mode = GB_OFF;
    gb_output.count = 0U;
    gb_output.rejected_windows = 0U;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s.x = 0.0;
    gb_output.bias_rad_s.y = 0.0;
    gb_output.bias_rad_s.z = 0.0;
    gb_output.variance_rad_s2.x = 0.0;
    gb_output.variance_rad_s2.y = 0.0;
    gb_output.variance_rad_s2.z = 0.0;
    return;
}

s = *(gb_input.rate_rad_s);

/* latched fault stays fault */
if (gb_state.mode == GB_FAULT) {
    gb_output.mode = GB_FAULT;
    gb_output.count = gb_state.count;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s.x = 0.0;
    gb_output.bias_rad_s.y = 0.0;
    gb_output.bias_rad_s.z = 0.0;
    gb_output.variance_rad_s2.x = 0.0;
    gb_output.variance_rad_s2.y = 0.0;
    gb_output.variance_rad_s2.z = 0.0;
    return;
}

/* READY: drift monitoring each cycle */
if (gb_state.mode == GB_READY) {
    dx = s.x - gb_state.bias_rad_s.x;
    dy = s.y - gb_state.bias_rad_s.y;
    dz = s.z - gb_state.bias_rad_s.z;
    nrm_delta = sqrt(dx * dx + dy * dy + dz * dz);
    if (nrm_delta <= gb_config.drift_limit_rad_s) {
        gb_state.drift_count = 0U;
    } else {
        gb_state.drift_count = gb_state.drift_count + 1U;
        if (gb_state.drift_count >= gb_config.drift_confirm_samples) {
            gb_state.mode = GB_COLLECT;
            gb_state.count = 0U;
            gb_state.has_previous = 0;
            gb_state.drift_count = 0U;
            gb_state.mean_rad_s = (adcs_vec3_t){0, 0, 0};
            gb_state.m2_rad_s2 = (adcs_vec3_t){0, 0, 0};
            gb_state.previous_rate_rad_s = (adcs_vec3_t){0, 0, 0};
            /* rejected_windows unchanged */
        }
    }
    gb_output.mode = gb_state.mode;
    gb_output.count = gb_state.count;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s = gb_state.bias_rad_s;
    gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
    return;
}

/* otherwise valid enabled cycle runs in COLLECT */
if (gb_state.mode != GB_COLLECT) {
    gb_state.mode = GB_COLLECT;
    gb_state.count = 0U;
    gb_state.has_previous = 0;
    gb_state.drift_count = 0U;
    gb_state.mean_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.m2_rad_s2 = (adcs_vec3_t){0, 0, 0};
    gb_state.previous_rate_rad_s = (adcs_vec3_t){0, 0, 0};
}

/* COLLECT sampling */
nrm = sqrt(s.x * s.x + s.y * s.y + s.z * s.z);
keep = 1U;
rejection_triggered = 0;
if (nrm > gb_config.stationary_limit_rad_s) {
    gb_output.rejection = GB_REJECT_RATE;
    keep = 0U;
    rejection_triggered = 1;
} else if (gb_state.has_previous) {
    dx = s.x - gb_state.previous_rate_rad_s.x;
    dy = s.y - gb_state.previous_rate_rad_s.y;
    dz = s.z - gb_state.previous_rate_rad_s.z;
    nrm_delta = sqrt(dx * dx + dy * dy + dz * dz);
    if (nrm_delta > gb_config.max_sample_delta_rad_s) {
        gb_output.rejection = GB_REJECT_STEP;
        keep = 0U;
        rejection_triggered = 1;
    }
} else {
    /* first sample in window with finite rate within limit: accepted unchanged */
    keep = 1U;
}

if (keep == 0U) {
    gb_state.count = 0U;
    gb_state.has_previous = 0;
    gb_state.mean_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.m2_rad_s2 = (adcs_vec3_t){0, 0, 0};
    gb_state.previous_rate_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.rejected_windows = gb_state.rejected_windows + 1U;
} else {
    uint32_t n;
    if (!gb_state.has_previous) {
        gb_state.mean_rad_s = s;
        gb_state.m2_rad_s2 = (adcs_vec3_t){0, 0, 0};
        gb_state.count = 1U;
        gb_state.has_previous = 1;
    } else {
        dx = s.x - gb_state.mean_rad_s.x;
        dy = s.y - gb_state.mean_rad_s.y;
        dz = s.z - gb_state.mean_rad_s.z;
        n = gb_state.count + 1U;
        gb_state.mean_rad_s.x += dx / (double)n;
        gb_state.mean_rad_s.y += dy / (double)n;
        gb_state.mean_rad_s.z += dz / (double)n;
        gb_state.m2_rad_s2.x += dx * (s.x - gb_state.mean_rad_s.x);
        gb_state.m2_rad_s2.y += dy * (s.y - gb_state.mean_rad_s.y);
        gb_state.m2_rad_s2.z += dz * (s.z - gb_state.mean_rad_s.z);
        gb_state.count = n;
    }
    gb_state.previous_rate_rad_s = s;

    /* required_samples gate */
    if (gb_state.count == gb_config.required_samples) {
        var_ax = gb_state.m2_rad_s2.x / (double)gb_state.count;
        var_ay = gb_state.m2_rad_s2.y / (double)gb_state.count;
        var_az = gb_state.m2_rad_s2.z / (double)gb_state.count;
        limit_std = gb_config.max_stddev_rad_s * gb_config.max_stddev_rad_s;
        if ((var_ax > limit_std) || (var_ay > limit_std) || (var_az > limit_std)) {
            gb_output.rejection = GB_REJECT_VARIANCE;
            gb_state.count = 0U;
            gb_state.has_previous = 0;
            gb_state.mean_rad_s = (adcs_vec3_t){0, 0, 0};
            gb_state.m2_rad_s2 = (adcs_vec3_t){0, 0, 0};
            gb_state.previous_rate_rad_s = (adcs_vec3_t){0, 0, 0};
            gb_state.rejected_windows = gb_state.rejected_windows + 1U;
            rejection_triggered = 1;
        } else {
            gb_state.mode = GB_READY;
            gb_state.bias_rad_s = gb_state.mean_rad_s;
            gb_state.variance_rad_s2 = (adcs_vec3_t){var_ax, var_ay, var_az};
            gb_state.drift_count = 0U;
        }
    }
}

/* fault latch on rejection count */
if ((rejection_triggered != 0) &&
    (gb_state.rejected_windows >= gb_config.max_rejected_windows)) {
    gb_state.mode = GB_FAULT;
    gb_state.count = 0U;
    gb_state.has_previous = 0;
    gb_state.drift_count = 0U;
    gb_state.mean_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.m2_rad_s2 = (adcs_vec3_t){0, 0, 0};
    gb_state.previous_rate_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.bias_rad_s = (adcs_vec3_t){0, 0, 0};
    gb_state.variance_rad_s2 = (adcs_vec3_t){0, 0, 0};
}

/* final publish */
gb_output.mode = gb_state.mode;
gb_output.count = gb_state.count;
gb_output.rejected_windows = gb_state.rejected_windows;

if (gb_state.mode == GB_READY) {
    gb_output.bias_rad_s = gb_state.bias_rad_s;
    gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
} else {
    gb_output.bias_rad_s.x = 0.0;
    gb_output.bias_rad_s.y = 0.0;
    gb_output.bias_rad_s.z = 0.0;
    if (gb_state.mode == GB_COLLECT && gb_output.rejection == GB_REJECT_NONE &&
        (gb_state.count > 0U)) {
        gb_output.variance_rad_s2.x = gb_state.m2_rad_s2.x / (double)gb_state.count;
        gb_output.variance_rad_s2.y = gb_state.m2_rad_s2.y / (double)gb_state.count;
        gb_output.variance_rad_s2.z = gb_state.m2_rad_s2.z / (double)gb_state.count;
    } else {
        gb_output.variance_rad_s2.x = 0.0;
        gb_output.variance_rad_s2.y = 0.0;
        gb_output.variance_rad_s2.z = 0.0;
    }
}
